mapper.select:
SELECT cdd.ID_CONSTANCIA_DETALLE AS idConstanciaDetalle, cdd.RAZON_SOCIAL_PROV AS razonSocialProv, cdd.NRO_DOC_PROVEEDOR AS nroProvedor, to_char(cd.FECHA_PAGO, 'dd/mm/yyyy') AS fechaDoc, cdd.TIPO_COMPROBANTE AS tipoComprobante, cdd.NRO_COMPROBANTE AS nroComprobante, cdd.NRO_CONSTANCIA AS nroConstancia, cdd.MONTO_DEPOSITO AS monedaMonto FROM CONSTANCIA_DETRACCION cd INNER JOIN CONSTANCIA_DETRACCION_DETALLE cdd ON cd.ID_CONSTANCIA_DETR = cdd.ID_CONSTANCIA_DETR WHERE 1 = 1
AND cdd.RAZON_SOCIAL_PROV LIKE '%' || #{razonSocial} ||'%'
AND cd.FECHA_PAGO >= #{fechaInicio}
AND cd.FECHA_PAGO <= #{fechaFin}
AND cdd.NRO_COMPROBANTE LIKE '%' || #{nroComprobante} || '%'
AND cdd.NRO_DOC_PROVEEDOR LIKE '%' || #{ruc} || '%'
ORDER BY cd.FECHA_PAGO DESC;
